// Shape the Clip Studio publish payload into YouTube-ready fields.
const b = $json.body || $json;
const m = b.metadata || {};
const hashtags = Array.isArray(m.hashtags) ? m.hashtags.join(' ') : '';
const description = [m.description || '', hashtags ? '\n\n' + hashtags : ''].join('').trim().slice(0, 4900);
const tags = Array.isArray(m.tags) ? m.tags.join(',').slice(0, 450) : '';
// #Shorts in title or description helps Shorts classification for vertical <3min uploads
let title = (m.title || 'Untitled Short').slice(0, 95);
return { json: {
  publication_id: b.publication_id,
  project_id: b.project_id,
  video_url: b.video_url,
  title,
  description: description || '#Shorts',
  tags,
} };

// Pull the YouTube video id out of the upload response regardless of shape
// (top-level id / id.videoId / snippet.resourceId.videoId), with a last-resort
// scan for an 11-char YouTube-id-shaped token.
const y = $json || {};
let id = (y.id && typeof y.id === 'object') ? y.id.videoId : y.id;
id = id || y?.snippet?.resourceId?.videoId || y.videoId;
if (!id) { const m = JSON.stringify(y).match(/"([A-Za-z0-9_-]{11})"/); id = m ? m[1] : null; }
return { json: { video_id: id, youtube_url: id ? ('https://youtube.com/shorts/' + id) : null } };
